package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.geometry.Vector;
import org.apache.commons.math3.geometry.euclidean.oned.Euclidean1D;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Embedding;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testRevertWithStandardDirection() {
        // Setup: Line passing through (1, 2, 3) with direction (1, 0, 0)
        Vector3D origin = new Vector3D(1.0, 2.0, 3.0);
        Vector3D direction = new Vector3D(1.0, 0.0, 0.0);
        Line line = new Line(origin, origin.add(direction));

        // Execute
        Line reverted = line.revert();

        // Verify: 
        // The method calculates: new origin = zero, new direction = zero - direction
        // zero is (0,0,0). 
        // new direction = (0,0,0) - (1,0,0) = (-1,0,0)

        assertNotNull("Reverted line should not be null", reverted);

        // Check origin is (0,0,0)
        assertEquals("Reverted origin X should be 0", 0.0, reverted.getOrigin().getX(), EPSILON);
        assertEquals("Reverted origin Y should be 0", 0.0, reverted.getOrigin().getY(), EPSILON);
        assertEquals("Reverted origin Z should be 0", 0.0, reverted.getOrigin().getZ(), EPSILON);

        // Check direction is (-1, 0, 0)
        // Note: Line direction is normalized in Apache Commons Math, 
        // so we check the unit vector direction.
        Vector3D expectedDir = new Vector3D(-1.0, 0.0, 0.0);
        assertEquals("Reverted direction X should be -1", expectedDir.getX(), reverted.getDirection().getX(), EPSILON);
        assertEquals("Reverted direction Y should be 0", expectedDir.getY(), reverted.getDirection().getY(), EPSILON);
        assertEquals("Reverted direction Z should be 0", expectedDir.getZ(), reverted.getDirection().getZ(), EPSILON);
    }




}

package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.geometry.Vector;
import org.apache.commons.math3.geometry.euclidean.oned.Euclidean1D;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Embedding;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen0Test {

    private static final double EPSILON = 1e-10;



    @Test
    public void testRevertWithDiagonalDirection() {
        // Setup: Line with direction (1, 1, 1)
        Vector3D origin = new Vector3D(5.0, 5.0, 5.0);
        Vector3D direction = new Vector3D(1.0, 1.0, 1.0);
        Line line = new Line(origin, origin.add(direction));

        // Execute
        Line reverted = line.revert();

        // Verify:
        // new direction = (0,0,0) - normalized(1,1,1) 
        // normalized(1,1,1) is (1/sqrt(3), 1/sqrt(3), 1/sqrt(3))
        // so new direction is (-1/sqrt(3), -1/sqrt(3), -1/sqrt(3))

        double invSqrt3 = 1.0 / Math.sqrt(3.0);
        Vector3D expectedDir = new Vector3D(-invSqrt3, -invSqrt3, -invSqrt3);

        assertEquals("Reverted origin should be zero", 0.0, reverted.getOrigin().getNorm(), EPSILON);
        assertEquals("Reverted direction X mismatch", expectedDir.getX(), reverted.getDirection().getX(), EPSILON);
        assertEquals("Reverted direction Y mismatch", expectedDir.getY(), reverted.getDirection().getY(), EPSILON);
        assertEquals("Reverted direction Z mismatch", expectedDir.getZ(), reverted.getDirection().getZ(), EPSILON);
    }


}

package org.apache.commons.math3.geometry.euclidean.threed;

