import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen0Test {

    private static final double EPSILON = 1e-10;





    @Test
    public void testRevertIsSimilarToOriginalDirectionInverse() {
        // Setup
        Vector3D origin = new Vector3D(10, -10, 5);
        Vector3D direction = new Vector3D(0, 1, 0);
        Line line = new Line(origin, origin.add(direction));

        // Execute
        Line reverted = line.revert();

        // Verify similarity: 
        // A line is similar to another if they have the same direction or opposite direction.
        // However, the revert method specifically flips the direction vector.
        // The new direction is (0, -1, 0).
        Vector3D expectedDir = new Vector3D(0, -1, 0);
        assertEquals("Direction should be exactly inverted", expectedDir.getY(), reverted.getDirection().getY(), EPSILON);
    }
}
